INTENT
Extend the existing URL shortener's in-process rate limiter so that a caller presenting a recognised X-API-Key on link creation is throttled against that key's own per-minute quota (declared in the SHORTENER_API_KEYS environment variable) instead of the shared per-IP budget, while callers with no key or an unrecognised key keep today's per-IP behaviour exactly and redirect throttling is untouched.

DESIGN
{
  "configuration": [
    {
      "default": "\"\" (empty string; no keys configured, key limiter inert)",
      "name": "SHORTENER_API_KEYS",
      "purpose": "Comma-separated NAME:QUOTA pairs declaring recognised API keys and their per-minute POST /api/links quota, e.g. \"alpha:100,beta:20\". Exact name, no LINKS_ prefix. Whitespace around each name and quota is stripped. An entry is accepted only if it has exactly one ':' separator, a non-empty name after stripping, and a quota that parses as an integer >= 1; every other entry (\"broken\", \"beta:notanumber\", \"gamma:0\", \" :5 \") is skipped without raising. On duplicate names the last declaration wins. Parsed once at process configuration time into an immutable mapping."
    },
    {
      "default": "true",
      "name": "LINKS_RATE_LIMIT_ENABLED",
      "purpose": "Master switch for the whole middleware. When false (case-insensitive \"false\"/\"0\"/\"no\"), neither the per-IP nor the per-key limiter is consulted and no bucket state is created."
    },
    {
      "default": "60",
      "name": "LINKS_RATE_LIMIT_MAX",
      "purpose": "Per-IP request allowance inside LINKS_RATE_LIMIT_WINDOW_SECONDS for POST /api/links. Applies unchanged to unkeyed, blank-keyed and unknown-keyed creation requests."
    },
    {
      "default": "60",
      "name": "LINKS_RATE_LIMIT_WINDOW_SECONDS",
      "purpose": "Width in seconds of the per-IP sliding window. Does not affect the per-key window, which is fixed at 60 seconds."
    },
    {
      "default": "./links.db",
      "name": "LINKS_DB_PATH",
      "purpose": "Filesystem path of the SQLite database file. Tests and implementation both bind to this exact name."
    },
    {
      "default": "http://localhost:8000",
      "name": "LINKS_BASE_URL",
      "purpose": "Origin used to build the short_url field returned by POST /api/links and GET /api/links/{code}/stats. Trailing slashes are stripped."
    },
    {
      "default": "7",
      "name": "LINKS_CODE_LENGTH",
      "purpose": "Number of base62 characters in a generated short code."
    },
    {
      "default": "5",
      "name": "LINKS_CODE_MAX_ATTEMPTS",
      "purpose": "Bounded number of insert attempts when a generated code collides with the UNIQUE constraint before the request fails with 503."
    },
    {
      "default": "0",
      "name": "LINKS_DEFAULT_TTL_SECONDS",
      "purpose": "Default lifetime applied when the create request omits expires_in_seconds. 0 means the link never expires."
    },
    {
      "default": "2048",
      "name": "LINKS_MAX_URL_LENGTH",
      "purpose": "Maximum accepted length of the target URL in POST /api/links."
    }
  ],
  "data_model": [
    {
      "fields": [
        {
          "constraints": "PRIMARY KEY AUTOINCREMENT, not null, never exposed in any response",
          "name": "id",
          "type": "INTEGER"
        },
        {
          "constraints": "NOT NULL, UNIQUE (this constraint is the sole enforcement point for short-code uniqueness)",
          "name": "code",
          "type": "TEXT"
        },
        {
          "constraints": "NOT NULL, length <= LINKS_MAX_URL_LENGTH",
          "name": "target_url",
          "type": "TEXT"
        },
        {
          "constraints": "NOT NULL, RFC3339 UTC, default set by the application",
          "name": "created_at",
          "type": "TEXT"
        },
        {
          "constraints": "NULLABLE; NULL means never expires",
          "name": "expires_at",
          "type": "TEXT"
        }
      ],
      "indexes": [
        "Implicit UNIQUE index on links.code, created by the UNIQUE constraint. This is the hot-path index: GET /{code} is a single equality lookup on code and would otherwise full-scan links on every redirect.",
        "No index on target_url: it is never queried by value."
      ],
      "name": "links",
      "purpose": "Persisted short links. UNCHANGED by this work: app/db.py SCHEMA_STATEMENTS is not edited and PRAGMA table_info(links) returns exactly today's columns. Reproduced here so implementation and tests agree on the read path."
    },
    {
      "fields": [
        {
          "constraints": "PRIMARY KEY AUTOINCREMENT, not null",
          "name": "id",
          "type": "INTEGER"
        },
        {
          "constraints": "NOT NULL, FOREIGN KEY -> links(id) ON DELETE CASCADE",
          "name": "link_id",
          "type": "INTEGER"
        },
        {
          "constraints": "NOT NULL, RFC3339 UTC",
          "name": "clicked_at",
          "type": "TEXT"
        }
      ],
      "indexes": [
        "Index on clicks(link_id, clicked_at) \u2014 GET /api/links/{code}/stats does COUNT(*) and MAX(clicked_at) filtered by link_id; without it the stats query scans the whole clicks table, which is the fastest-growing table in the service."
      ],
      "name": "clicks",
      "purpose": "Per-redirect click records feeding the stats endpoint. UNCHANGED by this work; no IP address, no user identity, no API key is stored."
    },
    {
      "fields": [
        {
          "constraints": "Namespaced identity: \"ip:\" + sha256(boot_salt + client_host) for per-IP creation buckets, \"rip:\" + sha256(boot_salt + client_host) for the per-IP redirect bucket, \"key:\" + sha256(boot_salt + raw_api_key) for recognised API keys only. The raw key and the raw IP never appear as a key or a value. Unknown/blank/case-mismatched key values never create a \"key:\" entry, so attacker-supplied headers cannot grow the map.",
          "name": "bucket_id",
          "type": "str (dict key)"
        },
        {
          "constraints": "Monotonic-clock timestamps of accepted requests inside the window; entries older than the bucket's window are popped on each touch. Length is bounded by the bucket's limit.",
          "name": "timestamps",
          "type": "collections.deque[float]"
        },
        {
          "constraints": ">= 1. LINKS_RATE_LIMIT_MAX for ip buckets, LINKS_RATE_LIMIT_MAX * REDIRECT_LIMIT_MULTIPLIER for rip buckets, the key's declared quota for key buckets.",
          "name": "limit",
          "type": "int"
        },
        {
          "constraints": "LINKS_RATE_LIMIT_WINDOW_SECONDS for ip and rip buckets; fixed 60.0 for key buckets regardless of that setting.",
          "name": "window_seconds",
          "type": "float"
        },
        {
          "constraints": "Monotonic timestamp of the last touch; drives MAX_TRACKED_KEYS LRU pruning, which now spans ip, rip and key namespaces in one map so total tracked buckets stay bounded.",
          "name": "last_seen",
          "type": "float"
        }
      ],
      "indexes": [
        "Single dict keyed by bucket_id gives O(1) lookup on the hot path; no scan. Pruning is the existing MAX_TRACKED_KEYS eviction of least-recently-seen entries."
      ],
      "name": "RateLimitBucket (in-process only, app/ratelimit.py)",
      "purpose": "Sliding-window counter state held in a single process-local dict inside RateLimitMiddleware. Never persisted, never logged, lost on restart. Not a SQLite table: no CREATE statement is added anywhere."
    },
    {
      "fields": [
        {
          "constraints": "Byte-exact, case-sensitive; leading/trailing whitespace stripped at parse time. Held only in memory; never written to SQLite, logs, response bodies or headers.",
          "name": "key",
          "type": "str"
        },
        {
          "constraints": ">= 1; entries whose quota is 0, negative or non-numeric are dropped during parsing",
          "name": "quota",
          "type": "int"
        }
      ],
      "indexes": [
        "Plain dict lookup by exact key string on each POST /api/links; O(1), no scan."
      ],
      "name": "ApiKeyQuotas (in-process config snapshot, app/config.py)",
      "purpose": "Immutable mapping from raw key string to integer per-minute quota, parsed once from SHORTENER_API_KEYS at process configuration time."
    }
  ],
  "decisions": [
    {
      "choice": "A separate bucket namespace (\"key:\"<hash>) consulted instead of the IP bucket for recognised-key creations; the IP bucket is not touched at all for those requests, and the key bucket is not touched for unkeyed ones.",
      "decision": "Where the per-key allowance lives relative to the per-IP allowance",
      "rationale": "A caller who exhausts alpha's quota can still create links with beta or with no key from the same address, and an exhausted IP bucket never blocks a paying key holder \u2014 exactly the independence the acceptance criteria describe.",
      "rejected": [
        "Decrementing both buckets: alpha's 100 successes would silently exhaust the IP budget of 10 and the 11th request would 429 despite quota remaining.",
        "Raising the IP limit when a key is present: quotas would still be shared between two keys behind one NAT address."
      ]
    },
    {
      "choice": "Fall through to today's per-IP path with no per-key state created. Header name matched case-insensitively; value stripped, and if empty treated as absent; value compared byte-exactly so ALPHA never matches alpha.",
      "decision": "How an unrecognised, blank or wrong-case X-API-Key is treated",
      "rationale": "Ten creations with an unknown key gamma succeed and the 11th 429s at the IP budget, identical to sending no header, so a bad key gives an attacker no capability and no way to inflate limiter memory with arbitrary header values.",
      "rejected": [
        "Rejecting unknown keys with 401: breaks the criterion that unknown keys behave like unkeyed callers and adds an auth surface the service does not have.",
        "Creating a bucket per observed header value: unbounded memory from attacker-chosen headers, defeating MAX_TRACKED_KEYS."
      ]
    },
    {
      "choice": "Fixed 60.0 seconds, independent of LINKS_RATE_LIMIT_WINDOW_SECONDS.",
      "decision": "Window width used by the key limiter",
      "rationale": "Quotas in SHORTENER_API_KEYS are declared as requests per minute, so with LINKS_RATE_LIMIT_WINDOW_SECONDS=1 and alpha:2 the third creation inside one minute is still refused; the operator's IP-window tuning cannot accidentally multiply a key's quota by sixty.",
      "rejected": [
        "Reusing the IP window: alpha:2 with a 1s window would allow 120 creations a minute.",
        "A second env var for the key window: another name for tests and code to disagree about, with no criterion needing it."
      ]
    },
    {
      "choice": "Fail-soft, entry by entry, at process configuration time: split on ',', strip each side of a single ':', require a non-empty name and an integer quota >= 1, skip anything else, last duplicate name wins, empty/unset yields an empty mapping.",
      "decision": "Parsing policy for SHORTENER_API_KEYS",
      "rationale": "\"alpha:100,broken,beta:notanumber,gamma:0, :5 ,delta:7\" boots successfully with alpha at 100 and delta at 7 while the junk entries degrade to per-IP limiting, and \" alpha : 100 \" still works \u2014 a typo in one entry never takes the service down.",
      "rejected": [
        "Raising on malformed input: a single stray comma in an operator's env file causes a crash-loop with no shortener at all.",
        "Logging the skipped entries verbatim: would write key material into log records, which the privacy constraint forbids; the count of skipped entries may be logged, never the text."
      ]
    },
    {
      "choice": "404 with envelope code \"not_found\" and a single generic message, byte-identical for expired and never-existed codes on GET /{code}. Only GET /api/links/{code}/stats reveals the distinction, via its expired boolean, and only for codes that exist.",
      "decision": "What a request for an expired code returns and whether it is distinguishable from a code that never existed",
      "rationale": "A distinct 410 on the redirect path would turn the shortener into an oracle: an attacker enumerating codes could tell which ones were ever issued, which is exactly what ran

ACCEPTANCE CRITERIA
- With SHORTENER_API_KEYS="alpha:100,beta:20", LINKS_RATE_LIMIT_ENABLED=true and LINKS_RATE_LIMIT_MAX=10, 100 consecutive POST /api/links requests carrying header X-API-Key: alpha from one client address all return 201.
- Under the same configuration, the 101st POST /api/links with X-API-Key: alpha returns 429, the body is {"error":{"code":"rate_limited","message":...}}, and the links table still holds exactly 100 rows.
- Under the same configuration, 20 creations with X-API-Key: beta return 201 and the 21st returns 429, showing quotas are read per key and not shared.
- After X-API-Key: alpha has been throttled to 429, the next POST /api/links with X-API-Key: beta from the same client address returns 201.
- After X-API-Key: alpha has been throttled to 429, a POST /api/links from the same client address with no X-API-Key header returns 201 (the key bucket and the IP bucket are independent).
- With no X-API-Key header and LINKS_RATE_LIMIT_MAX=10, the 11th POST /api/links from one client address returns 429 with a Retry-After header, identical to current behaviour.
- With SHORTENER_API_KEYS="alpha:100", 10 creations carrying X-API-Key: gamma (an unknown key) return 201 and the 11th returns 429, i.e. an unknown key is limited by the per-IP budget of 10, not by any key quota.
- A POST /api/links carrying X-API-Key with an empty or whitespace-only value is treated as having no key: the per-IP budget of LINKS_RATE_LIMIT_MAX applies.
- Key matching is exact and case-sensitive: with SHORTENER_API_KEYS="alpha:100", requests carrying X-API-Key: ALPHA are limited by the per-IP budget, not by the quota 100.
- Every 429 produced by the key limiter carries a Retry-After header whose value parses as an integer >= 1 and <= 60, and carries Cache-Control: no-store.
- With SHORTENER_API_KEYS="alpha:1" and LINKS_RATE_LIMIT_MAX=10, after X-API-Key: alpha has been refused a creation with 429, 50 GET /{code} redirect requests carrying X-API-Key: alpha all return 307 (redirects are never limited by key).
- With SHORTENER_API_KEYS unset or empty, every existing test in tests/test_rate_limit.py passes unchanged and per-IP creation and redirect limiting behave exactly as today.
- With SHORTENER_API_KEYS="alpha:100,broken,beta:notanumber,gamma:0, :5 ,delta:7" the process starts successfully; X-API-Key: alpha is limited at 100 and X-API-Key: delta at 7, while broken, beta and gamma are treated as unknown keys and fall back to the per-IP limit.
- With SHORTENER_API_KEYS=" alpha : 100 " (surrounding whitespace), X-API-Key: alpha is limited at 100 creations per minute.
- With SHORTENER_API_KEYS="alpha:5,alpha:100", X-API-Key: alpha is limited at 100 (the last declaration for a duplicate name wins) and the service does not error at startup.
- With LINKS_RATE_LIMIT_ENABLED=false and SHORTENER_API_KEYS="alpha:2", 15 consecutive creations with X-API-Key: alpha all return 201.
- With LINKS_RATE_LIMIT_WINDOW_SECONDS=1 and SHORTENER_API_KEYS="alpha:2", the third creation with X-API-Key: alpha inside one minute returns 429 (the key window is one minute independent of the IP window setting).
- After a run of keyed traffic, the literal string of every configured key name appears in no file under LINKS_DB_PATH's directory, in no emitted log record and in no response body or response header.
- GET /api/links/{code}/stats and GET /health return their normal responses regardless of whether an X-API-Key header is present or the key is over quota.
- No new table or column exists after startup: PRAGMA table_info(links) and PRAGMA table_info(clicks) return exactly the columns defined in app/db.py SCHEMA_STATEMENTS today.
- A POST /api/links refused by the key limiter writes no links row and no clicks row, because the refusal happens in the ASGI middleware before routing and body parsing.

CONSTRAINTS
- Python with FastAPI 0.115.6, Starlette 0.41.3, pydantic 2.10.4 as pinned in requirements.txt; no new runtime dependency may be added.
- No SQLite schema change: app/db.py SCHEMA_STATEMENTS must remain as-is and no key, quota or counter may be persisted to the database.
- No admin surface: keys and quotas are read only from the environment variable SHORTENER_API_KEYS, using that exact name (not the LINKS_ prefix), at process configuration time.
- Limiting must stay in the existing in-process ASGI middleware (app/ratelimit.py RateLimitMiddleware) which runs before routing and body parsing, so refused requests never open a database connection.
- Additive only: the per-IP creation limit for unkeyed and unknown-key requests, and the per-IP redirect throttle (REDIRECT_LIMIT_MULTIPLIER path), must behave exactly as today; existing tests must pass unmodified.
- API key values are credentials: they must never be written to SQLite, to any log record, to any response body or header, and limiter state must key on the existing per-boot salted SHA-256 rather than the raw key, with all state lost on restart.
- The existing privacy posture is unchanged: no client IP address may be logged or persisted.
- Error responses keep the stable envelope {"error":{"code":...,"message":...}}; the 429 keeps code "rate_limited" and Cache-Control: no-store.
- Retry-After must be a whole number of seconds, at least 1, computed as the time until the caller's window releases capacity.
- Limiter memory must stay bounded: unknown or attacker-supplied X-API-Key values must not create per-key state, and total tracked buckets must remain subject to the MAX_TRACKED_KEYS pruning already in place.
- Malformed or absent SHORTENER_API_KEYS must not prevent the service from starting, matching the fail-soft configuration behaviour in app/config.py.
- The X-API-Key header must be matched case-insensitively by header name (HTTP rules) while the key value itself is compared byte-exactly.
- Per-key quota is expressed in requests per minute for POST /api/links only; redirects and stats are never limited by key.

Implement this design as a complete, runnable service. Include requirements.txt with pinned versions. The next stage generates tests against the files you return and reviews them line by line, so return the code you would defend in that review.

payload.text:
{"files":[{"path":"tests/_pipeline_support.py","content":""""Shared fixtures for the delivery-pipeline suite.

Every test gets a brand new SQLite file (LINKS_DB_PATH), a freshly imported
application object (so process-level configuration is re-read and the
in-process rate limiter starts with an empty bucket map) and a stubbed name
resolver.  No test touches the network, no test sleeps, no test shares a
database or limiter state with another test, and no test depends on ordering.

This module is deliberately not a conftest.py: the repository already has one
and two conftest modules in the same directory are not possible.  Fixtures are
imported by name into each test module instead.
"""
from __future__ import annotations

import importlib
import ipaddress
import secrets
import socket
import sqlite3
import string
import sys
from contextlib import ExitStack
from dataclasses import dataclass
from datetime import datetime, timezone
import os
from pathlib import Path
from typing import Any, Dict, List, Optional

import pytest
from fastapi.testclient import TestClient

ROOT = Path(__file__).resolve().parents[1]
for _candidate in (ROOT, ROOT / "src"):
    if _candidate.is_dir() and str(_candidate) not in sys.path:
        sys.path.insert(0, str(_candidate))

API_KEY_HEADER = "X-API-Key"
PUBLIC_IPV4 = "93.184.216.34"
PUBLIC_IPV6 = "2606:2800:220:1:248:1893:25c8:1946"
TS_FORMAT = "%Y-%m-%dT%H:%M:%S.%fZ"
BASE62 = string.ascii_letters + string.digits
CODE_LENGTH = 7

#: Exactly the environment variable names the service reads.  Rate limiting is
#: off by default so that only the rate limit tests pay for it.
BASE_ENV: Dict[str, str] = {
    "LINKS_BASE_URL": "http://testserver",
    "LINKS_CODE_LENGTH": str(CODE_LENGTH),
    "LINKS_CODE_MAX_ATTEMPTS": "5",
    "LINKS_MAX_URL_LENGTH": "2048",
    "LINKS_DEFAULT_TTL_DAYS": "30",
    "LINKS_RATE_LIMIT_ENABLED": "false",
    "LINKS_RATE_LIMIT_MAX": "10",
    "LINKS_RATE_LIMIT_WINDOW_SECONDS": "60",
    "LINKS_TRUST_FORWARDED_FOR": "false",
    "LINKS_STATS_DEFAULT_LIMIT": "50",
    "LINKS_STATS_MAX_LIMIT": "500",
    "LINKS_DNS_RESOLUTION_ENABLED": "true",
    "LINKS_LOG_LEVEL": "WARNING",
    "SHORTENER_API_KEYS": "",
}

APP_MODULE_CANDIDATES = (
    "app.main",
    "app",
    "main",
    "src.app.main",
    "src.main",
)

_APP_MODULE_NAME: Optional[str] = None
_UNSET = object()


# ---------------------------------------------------------------- app import
def _purge_root(root: str) -> None:
    for name in list(sys.modules):
        if name == root or name.startswith(root + "."):
            del sys.modules[name]


def _get_app_object(module: Any):
    obj = getattr(module, "app", None)
    if obj is not None and hasattr(obj, "router"):
        return obj
    factory = getattr(module, "create_app", None)
    if callable(factory):
        try:
            built = factory()
        except Exception:  # pragma: no cover - depends on layout
            return None
        if built is not None and hasattr(built, "router"):
            return built
    return None


def _import_app_module():
    global _APP_MODULE_NAME
    problems: List[str] = []
    names = [_APP_MODULE_NAME] if _APP_MODULE_NAME else list(APP_MODULE_CANDIDATES)
    for name in names:
        _purge_root(name.split(".")[0])
        try:
            module = importlib.import_module(name)
        except Exception as exc:  # pragma: no cover - depends on layout
            problems.append("{0}: {1}: {2}".format(name, type(exc).__name__, exc))
            continue
        if _get_app_object(module) is None:
            problems.append("{0}: no ASGI `app` and no usable create_app()".format(name))
            continue
        _APP_MODULE_NAME = name
        return module
    raise RuntimeError(
        "Could not import the ASGI application. Tried:\n  " + "\n  ".join(problems)
    )


# --------------------------------------------------------------- DNS stubbing
class FakeDns:
    """Deterministic stand-in for the system resolver. No test hits the network."""

    def __init__(self) -> None:
        self.map: Dict[str, List[str]] = {}
        self.failures = set()
        self.lookups: List[str] = []

    def set(self, host: str, addresses) -> None:
        self.map[host.strip("[]").lower()] = list(addresses)

    def fail(self, host: str) -> None:
        self.failures.add(host.strip("[]").lower())

    def _addresses_for(self, host: str) -> List[str]:
        key = (host or "").strip("[]").lower()
        self.lookups.append(key)
        if key in self.failures:
            raise socket.gaierror(-2, "Name or service not known")
        if key in self.map:
            return list(self.map[key])
        try:
            ipaddress.ip_address(key)
            return [key]
        except ValueError:
            return [PUBLIC_IPV4]

    def getaddrinfo(self, host, port=0, family=0, type=0, proto=0, flags=0):
        try:
            portnum = int(port)
        except (TypeError, ValueError):
            portnum = 80
        out = []
        for addr in self._addresses_for(host):
            parsed = ipaddress.ip_address(addr)
            if parsed.version == 4:
                out.append((socket.AF_INET, socket.SOCK_STREAM, 6, "", (addr, portnum)))
            else:
                out.append(
                    (socket.AF_INET6, socket.SOCK_STREAM, 6, "", (addr, portnum, 0, 0))
                )
        return out

    def gethostbyname(self, host):
        for addr in self._addresses_for(host):
            if ipaddress.ip_address(addr).version == 4:
                return addr
        raise socket.gaierror(-2, "Name or service not known")

    def gethostbyname_ex(self, host):
        addrs = [
            a for a in self._addresses_for(host) if ipaddress.ip_address(a).version == 4
        ]
        return (host, [], addrs)


@pytest.fixture
def stub_dns(monkeypatch):
    resolver = FakeDns()
    # A decimal IPv4 literal is what the real resolver would decode; map it so a
    # service that leans on the resolver and one that parses the literal itself
    # are both required to block it.
    resolver.set("2130706433", ["127.0.0.1"])
    monkeypatch.setattr(socket, "getaddrinfo", resolver.getaddrinfo)
    monkeypatch.setattr(socket, "gethostbyname", resolver.gethostbyname)
    monkeypatch.setattr(socket, "gethostbyname_ex", resolver.gethostbyname_ex)
    return resolver


# ------------------------------------------------------------------- harness
@dataclass
class Harness:
    client: TestClient
    db_path: str
    module: Any
    env: Dict[str, str]

    # ---- HTTP ----
    def create(
        self,
        url=None,
        *,
        expires_at=None,
        api_key=_UNSET,
        headers=None,
        payload=None,
    ):
        body = payload
        if body is None:
            body = {}
            if url is not None:
                body["url"] = url
            if expires_at is not None:
                body["expires_at"] = expires_at
        hdrs = dict(headers or {})
        if api_key is not _UNSET:
            hdrs[API_KEY_HEADER] = api_key
        return self.client.post("/api/links", json=body, headers=hdrs)

    def visit(self, code, headers=None, api_key=_UNSET):
        hdrs = dict(headers or {})
        if api_key is not _UNSET:
            hdrs[API_KEY_HEADER] = api_key
        try:
            return self.client.get(
                "/" + str(code), headers=hdrs, follow_redirects=False
            )
        except TypeError:  # pragma: no cover - very old TestClient
            return self.client.get("/" + str(code), headers=hdrs, allow_redirects=False)

    def stats(self, code, headers=None, api_key=_UNSET, **params):
        hdrs = dict(headers or {})
        if api_key is not _UNSET:
            hdrs[API_KEY_HEADER] = api_key
        return self.client.get(
            "/api/links/{0}/stats".format(code), params=params or None, headers=hdrs
        )

    def health(self, api_key=_UNSET):
        hdrs = {}
        if api_key is not _UNSET:
            hdrs[API_KEY_HEADER] = api_key
        return self.client.get("/health", headers=hdrs)

    # ---- database ----
    def _rows(self, sql, params=()):
        con = sqlite3.connect(self.db_path)
        con.row_factory = sqlite3.Row
        try:
            return [dict(r) for r in con.execute(sql, params).fetchall()]
        except sqlite3.OperationalError as exc:
            raise AssertionError(
                "sqlite error {0!r} against {1}: does the service honour "
                "LINKS_DB_PATH and create its schema?".format(str(exc), self.db_path)
            )
        finally:
            con.close()

    def link_rows(self):
        return self._rows("SELECT * FROM links ORDER BY id")

    def click_rows(self):
        return self._rows("SELECT * FROM clicks ORDER BY id")

    def link_count(self) -> int:
        return len(self.link_rows())

    def click_count(self) -> int:
        return len(self.click_rows())

    def columns(self, table: str):
        return [r["name"] for r in self._rows("PRAGMA table_info({0})".format(table))]

    def table_names(self):
        return [
            r["name"]
            for r in self._rows("SELECT name FROM sqlite_master WHERE type = 'table'")
        ]

    def set_expiry(self, code: str, when: datetime) -> None:
        stamp = when.astimezone(timezone.utc).strftime(TS_FORMAT)
        con = sqlite3.connect(self.db_path)
        try:
            cur = con.execute(
                "UPDATE links SET expires_at = ? WHERE code = ?", (stamp, code)
            )
            con.commit()
            assert cur.rowcount == 1, "no links row with code {0!r}".format(code)
        finally:
            con.close()

    def disk_bytes(self) -> bytes:
        blob = b""
        for path in sorted(Path(self.db_path).parent.glob("*")):
            if path.is_file():
                blob += path.read_bytes()
        return blob


def link_target(row: Dict[str, Any]) -> Any:
    """Stored destination of a links row (implementation column is ``url``)."""
    if "url" in row:
        return row["url"]
    return row.get("target_url")


