CODE_RE = re.compile(r"^[A-Za-z0-9]{7}$")


def test_a_generator_returning_an_existing_code_is_retried_until_it_is_unique(service, force_codes):
    first = service.create("https://example.com/first")
    assert first.status_code == 201, first.text[:200]
    taken = first.json()["code"]

    stub = force_codes(service, [taken, taken, "Zq7Xk2M"])
    second = service.create("https://example.com/second")

    assert stub.calls >= 2, (
        "the code generator was consulted {0} time(s): the service did not retry "
        "after the UNIQUE collision".format(stub.calls)
    )
    assert second.status_code == 201, (
        "a collision must be retried, not surfaced as {0}: {1}".format(
            second.status_code, second.text[:200]
        )
    )
    code = second.json()["code"]
    assert code != taken, "the second link was handed the first link's code"
    assert CODE_RE.match(code), code

    stored = sorted(row["code"] for row in service.link_rows())
    assert stored == sorted([taken, code])
    assert len(set(stored)) == 2


def test_both_links_still_resolve_to_their_own_destination_after_a_collision(service, force_codes):
    taken = service.create("https://example.com/first").json()["code"]
    force_codes(service, [taken, "Zq7Xk2M"])

    second = service.create("https://example.com/second")
    assert second.status_code == 201, second.text[:200]
    code = second.json()["code"]

    assert service.visit(taken).headers["location"] == "https://example.com/first"
    assert service.visit(code).headers["location"] == "https://example.com/second"


def test_a_permanently_colliding_generator_gives_up_with_503_after_a_bounded_retry(make_app, force_codes):
    svc = make_app(LINKS_CODE_MAX_ATTEMPTS="3")
    taken = svc.create("https://example.com/first").json()["code"]

    stub = force_codes(svc, [taken] * 200)
    response = svc.create("https://example.com/second")

    assert stub.calls >= 2, (
        "generator consulted {0} time(s); the bounded retry loop never ran".format(
            stub.calls
        )
    )
    assert stub.calls <= 20, (
        "the retry loop is unbounded ({0} attempts): a hostile collision would "
        "hang the request".format(stub.calls)
    )
    assert response.status_code == 503, (
        "exhausted attempts must give up with 503, got {0}: {1}".format(
            response.status_code, response.text[:200]
        )
    )
    error = assert_error_envelope(response)
    assert error["code"] == "code_generation_failed", error
    assert svc.link_count() == 1, "the failed creation must not have written a row"
"},{"path":"tests/test_pipeline_rate_limit_keys.py","content":""""Rate limiting: per-IP budget, per-key quotas from SHORTENER_API_KEYS.

No test sleeps: every limiter test drives the limit inside one window.
"""
from _pipeline_support import (  # noqa: F401 - fixtures are imported by name
    API_KEY_HEADER,
    assert_error_envelope,
    make_app,
    service,
    stub_dns,
)

ON = {"LINKS_RATE_LIMIT_ENABLED": "true"}


def _url(i):
    return "https://example.com/target-{0}".format(i)


def _burst(svc, count, api_key=None, start=0):
    statuses = []
    for i in range(start, start + count):
        if api_key is None:
            response = svc.create(_url(i))
        else:
            response = svc.create(_url(i), api_key=api_key)
        statuses.append(response.status_code)
    return statuses


def _retry_after_seconds(response):
    raw = response.headers.get("retry-after")
    assert raw is not None, "a 429 must carry a Retry-After header"
    return int(raw)


# ------------------------------------------------------------ per-IP baseline
def test_the_eleventh_unkeyed_creation_is_refused_with_429_and_a_retry_after(make_app):
    svc = make_app(LINKS_RATE_LIMIT_MAX="10", **ON)

    assert _burst(svc, 10) == [201] * 10

    refused = svc.create(_url(10))

    assert refused.status_code == 429, (
        "the 11th creation in the window must be refused, got {0}: {1}".format(
            refused.status_code, refused.text[:200]
        )
    )
    error = assert_error_envelope(refused)
    assert error["code"] == "rate_limited", error
    assert _retry_after_seconds(refused) >= 1
    assert svc.link_count() == 10, "the throttled request must not have written a row"


# ------------------------------------------------------------- per-key quotas
def test_a_recognised_key_receives_its_full_declared_quota_of_one_hundred(make_app):
    svc = make_app(
        SHORTENER_API_KEYS="alpha:100,beta:20", LINKS_RATE_LIMIT_MAX="10", **ON
    )

    for i in range(100):
        response = svc.create(_url(i), api_key="alpha")
        assert response.status_code == 201, (
            "creation {0} of 100 with the recognised key alpha (quota 100, per-IP "
            "max 10) was refused with {1}: {2}".format(
                i + 1, response.status_code, response.text[:200]
            )
        )

    assert svc.link_count() == 100


def test_the_creation_past_a_keys_quota_is_refused_with_429_and_writes_no_row(make_app):
    svc = make_app(
        SHORTENER_API_KEYS="alpha:100,beta:20", LINKS_RATE_LIMIT_MAX="10", **ON
    )
    for i in range(100):
        assert svc.create(_url(i), api_key="alpha").status_code == 201, i

    refused = svc.create(_url(100), api_key="alpha")

    assert refused.status_code == 429, (
        "the 101st alpha creation must be refused, got {0}: {1}".format(
            refused.status_code, refused.text[:200]
        )
    )
    error = assert_error_envelope(refused)
    assert error["code"] == "rate_limited", error
    assert svc.link_count() == 100, "the refused creation wrote a links row"
    assert svc.click_count() == 0, "the refused creation wrote a clicks row"


def test_each_key_carries_its_own_quota_so_beta_stops_at_twenty(make_app):
    svc = make_app(
        SHORTENER_API_KEYS="alpha:100,beta:20", LINKS_RATE_LIMIT_MAX="10", **ON
    )

    assert _burst(svc, 20, api_key="beta") == [201] * 20

    refused = svc.create(_url(20), api_key="beta")

    assert refused.status_code == 429, (
        "beta's quota is 20, so the 21st must be refused, got {0}".format(
            refused.status_code
        )
    )
    assert assert_error_envelope(refused)["code"] == "rate_limited"
    assert svc.link_count() == 20


def test_an_exhausted_key_does_not_block_a_different_key_from_the_same_address(make_app):
    svc = make_app(SHORTENER_API_KEYS="alpha:2,beta:20", LINKS_RATE_LIMIT_MAX="10", **ON)
    assert _burst(svc, 2, api_key="alpha") == [201, 201]
    assert svc.create(_url(2), api_key="alpha").status_code == 429

    other = svc.create(_url(3), api_key="beta")

    assert other.status_code == 201, (
        "beta has its own quota and must not be blocked by alpha's exhaustion: "
        "{0}: {1}".format(other.status_code, other.text[:200])
    )
    assert svc.link_count() == 3


def test_an_exhausted_key_does_not_block_an_unkeyed_creation_from_the_same_address(make_app):
    svc = make_app(SHORTENER_API_KEYS="alpha:2", LINKS_RATE_LIMIT_MAX="10", **ON)
    assert _burst(svc, 2, api_key="alpha") == [201, 201]
    assert svc.create(_url(2), api_key="alpha").status_code == 429

    unkeyed = svc.create(_url(3))

    assert unkeyed.status_code == 201, (
        "the key bucket and the IP bucket are independent, got {0}: {1}".format(
            unkeyed.status_code, unkeyed.text[:200]
        )
    )


def test_keyed_successes_do_not_consume_the_per_ip_budget(make_app):
    svc = make_app(SHORTENER_API_KEYS="alpha:5", LINKS_RATE_LIMIT_MAX="10", **ON)

    assert _burst(svc, 5, api_key="alpha") == [201] * 5
    assert _burst(svc, 10, start=100) == [201] * 10, (
        "the five keyed creations were charged to the IP bucket as well"
    )

    refused = svc.create(_url(200))
    assert refused.status_code == 429
    assert svc.link_count() == 15


def test_an_unknown_key_is_limited_by_the_per_ip_budget_of_ten(make_app):
    svc = make_app(SHORTENER_API_KEYS="alpha:100", LINKS_RATE_LIMIT_MAX="10", **ON)

    assert _burst(svc, 10, api_key="gamma") == [201] * 10

    refused = svc.create(_url(10), api_key="gamma")

    assert refused.status_code == 429, (
        "an unknown key must fall back to the per-IP budget of 10, got {0}".format(
            refused.status_code
        )
    )
    assert assert_error_envelope(refused)["code"] == "rate_limited"
    assert svc.link_count() == 10


def test_a_blank_api_key_header_is_treated_as_no_key_at_all(make_app):
    svc = make_app(SHORTENER_API_KEYS="alpha:100", LINKS_RATE_LIMIT_MAX="3", **ON)

    assert svc.create(_url(0), api_key="").status_code == 201
    assert svc.create(_url(1), api_key="   ").status_code == 201
    assert svc.create(_url(2)).status_code == 201

    refused = svc.create(_url(3), api_key="  ")

    assert refused.status_code == 429, (
        "blank and absent keys share the per-IP budget of 3, got {0}".format(
            refused.status_code
        )
    )
    assert svc.link_count() == 3


def test_key_matching_is_case_sensitive_so_upper_case_alpha_gets_only_the_ip_budget(make_app):
    svc = make_app(SHORTENER_API_KEYS="alpha:100", LINKS_RATE_LIMIT_MAX="3", **ON)

    assert _burst(svc, 3, api_key="ALPHA") == [201] * 3

    refused = svc.create(_url(3), api_key="ALPHA")

    assert refused.status_code == 429, (
        "ALPHA must not match the declared key alpha, got {0}".format(
            refused.status_code
        )
    )
    assert svc.link_count() == 3


def test_a_key_limited_429_carries_retry_after_within_the_minute_and_no_store(make_app):
    svc = make_app(SHORTENER_API_KEYS="alpha:1", LINKS_RATE_LIMIT_MAX="10", **ON)
    assert svc.create(_url(0), api_key="alpha").status_code == 201

    refused = svc.create(_url(1), api_key="alpha")

    assert refused.status_code == 429, refused.text[:200]
    seconds = _retry_after_seconds(refused)
    assert 1 <= seconds <= 60, (
        "the key window is one minute, so Retry-After must be in [1, 60], got "
        + repr(seconds)
    )
    assert "no-store" in refused.headers.get("cache-control", "").lower(), (
        "a 429 must not be cached; Cache-Control was "
        + repr(refused.headers.get("cache-control"))
    )


def test_redirects_are_never_refused_because_a_key_is_over_its_creation_quota(make_app):
    svc = make_app(SHORTENER_API_KEYS="alpha:1", LINKS_RATE_LIMIT_MAX="10", **ON)
    created = svc.create(_url(0), api_key="alpha")
    assert created.status_code == 201, created.text[:200]
    code = created.json()["code"]
    assert svc.create(_url(1), api_key="alpha").status_code == 429

    for i in range(50):
        hop = svc.visit(code, api_key="alpha")
        assert hop.status_code == 307, (
            "redirect {0} of 50 with an over-quota key was refused with {1}".format(
                i + 1, hop.status_code
            )
        )

    assert svc.stats(code).json()["total_clicks"] == 50


# ------------------------------------------------------ SHORTENER_API_KEYS parsing
def test_junk_entries_do_not_stop_the_valid_ones_from_being_honoured(make_app):
    svc = make_app(
        SHORTENER_API_KEYS="alpha:100,broken,beta:notanumber,gamma:0, :5 ,delta:7",
        LINKS_RATE_LIMIT_MAX="2",
        **ON
    )

    assert svc.health().status_code == 200, "the service must boot with junk entries"
    assert _burst(svc, 7, api_key="delta") == [201] * 7, (
        "delta:7 survives the junk entries around it"
    )

    refused = svc.create(_url(7), api_key="delta")
    assert refused.status_code == 429, (
        "delta's quota is 7, so the 8th must be refused, got {0}".format(
            refused.status_code
        )
    )


def test_a_malformed_entry_leaves_its_key_on_the_per_ip_budget(make_app):
    svc = make_app(
        SHORTENER_API_KEYS="alpha:100,broken,beta:notanumber,gamma:0, :5 ,delta:7",
        LINKS_RATE_LIMIT_MAX="2",
        **ON
    )

    assert _burst(svc, 2, api_key="beta") == [201, 201]

    refused = svc.create(_url(2), api_key="beta")

    assert refused.status_code == 429, (
        "beta:notanumber is skipped, so beta gets the per-IP budget of 2, got "
        "{0}".format(refused.status_code)
    )
    assert svc.link_count() == 2


def test_whitespace_around_a_key_declaration_is_stripped(make_app):
    svc = make_app(SHORTENER_API_KEYS=" alpha : 100 ", LINKS_RATE_LIMIT_MAX="2", **ON)

    statuses = _burst(svc, 5, api_key="alpha")

    assert statuses == [201] * 5, (
        "' alpha : 100 ' must register alpha at quota 100, got " + repr(statuses)
    )


def test_the_last_declaration_of_a_duplicate_key_name_wins(make_app):
    svc = make_app(SHORTENER_API_KEYS="alpha:5,alpha:100", LINKS_RATE_LIMIT_MAX="2", **ON)

    assert svc.health().status_code == 200
    statuses = _burst(svc, 6, api_key="alpha")

    assert statuses == [201] * 6, (
        "the later alpha:100 must win over alpha:5, got " + repr(statuses)
    )


def test_disabling_the_limiter_ignores_key_quotas_entirely(make_app):
    svc = make_app(
        SHORTENER_API_KEYS="alpha:2",
        LINKS_RATE_LIMIT_ENABLED="false",
        LINKS_RATE_LIMIT_MAX="10",
    )

    statuses = _burst(svc, 15, api_key="alpha")

    assert statuses == [201] * 15, (
        "LINKS_RATE_LIMIT_ENABLED=false must disable the key limiter too, got "
        + repr(statuses)
    )
    assert svc.link_count() == 15


def test_the_key_window_stays_one_minute_when_the_ip_window_is_one_second(make_app):
    svc = make_app(
        SHORTENER_API_KEYS="alpha:2",
        LINKS_RATE_LIMIT_WINDOW_SECONDS="1",
        LINKS_RATE_LIMIT_MAX="10",
        **ON
    )

    assert _burst(svc, 2, api_key="alpha") == [201, 201]

    refused = svc.create(_url(2), api_key="alpha")

    assert refused.status_code == 429, (
        "the key window is a fixed minute, so a 1s IP window must not multiply "
        "alpha's quota; got {0}".format(refused.status_code)
    )
    assert svc.link_count() == 2


def test_stats_and_health_answer_normally_while_a_key_is_over_quota(make_app):
    svc = make_app(SHORTENER_API_KEYS="alpha:1", LINKS_RATE_LIMIT_MAX="10", **ON)
    code = svc.create(_url(0), api_key="alpha").json()["code"]
    assert svc.create(_url(1), api_key="alpha").status_code == 429

    stats = svc.stats(code, api_key="alpha")
    health = svc.health(api_key="alpha")

    assert stats.status_code == 200, stats.text[:200]
    assert stats.json()["code"] == code
    assert health.status_code == 200, health.text[:200]
    assert health.json()["status"] == "ok"
"},{"path":"tests/test_pipeline_key_hygiene.py","content":""""Key material never lands on disk, in logs or in responses; schema unchanged."""
import logging

from _pipeline_support import (  # noqa: F401 - fixtures are imported by name
    API_KEY_HEADER,
    assert_error_envelope,
    make_app,
    service,
    stub_dns,
)

# Exactly the columns app/db.py SCHEMA_STATEMENTS creates today.
LINKS_COLUMNS = ["id", "code", "url", "created_at", "expires_at"]
CLICKS_COLUMNS = ["id", "link_id", "clicked_at", "referrer", "user_agent"]


def test_no_configured_key_name_reaches_the_database_logs_or_a_response(make_app, caplog):
    caplog.set_level(logging.DEBUG)
    svc = make_app(
        SHORTENER_API_KEYS="alpha:2,delta:7",
        LINKS_RATE_LIMIT_ENABLED="true",
        LINKS_RATE_LIMIT_MAX="10",
    )

    responses = []
    for i in range(3):
        responses.append(svc.create("https://example.com/t{0}".format(i), api_key="alpha"))
    for i in range(3):
        responses.append(svc.create("https://example.com/u{0}".format(i), api_key="delta"))
    created = [r for r in responses if r.status_code == 201]
    assert created, "no creation succeeded, so this test proves nothing"
    code = created[0].json()["code"]
    responses.append(svc.visit(code, api_key="delta"))
    responses.append(svc.stats(code, api_key="alpha"))

    blob = svc.disk_bytes()
    log_text = caplog.text
    for name in ("alpha", "delta"):
        assert name.encode() not in blob, (
            "the key name {0!r} was written to a file under LINKS_DB_PATH".format(name)
        )
        assert name not in log_text, (
            "the key name {0!r} appears in a log record".format(name)
        )
        for response in responses:
            assert name not in response.text, (
                "the key name {0!r} was echoed in a response body".format(name)
            )
            for header, value in response.headers.items():
                assert name not in value, (
                    "the key name {0!r} was echoed in header {1}".format(name, header)
                )


def test_keyed_traffic_adds_no_table_and_no_column_to_the_database(make_app):
    svc = make_app(
        SHORTENER_API_KEYS="alpha:2",
        LINKS_RATE_LIMIT_ENABLED="true",
        LINKS_RATE_LIMIT_MAX="10",
    )
    for i in range(4):
        svc.create("https://example.com/t{0}".format(i), api_key="alpha")

    assert svc.columns("links") == LINKS_COLUMNS, svc.columns("links")
    assert svc.columns("clicks") == CLICKS_COLUMNS, svc.columns("clicks")
    tables = sorted(n for n in svc.table_names() if not n.startswith("sqlite_"))
    assert tables == ["clicks", "links"], (
        "rate limiter state must stay in process, not in SQLite; found " + repr(tables)
    )


def test_a_creation_refused_by_the_limiter_writes_neither_a_link_nor_a_click(make_app):
    svc = make_app(
        SHORTENER_API_KEYS="alpha:1",
        LINKS_RATE_LIMIT_ENABLED="true",
        LINKS_RATE_LIMIT_MAX="10",
    )
    assert svc.create("https://example.com/first", api_key="alpha").status_code == 201

    refused = svc.create("https://example.com/second", api_key="alpha")

    assert refused.status_code == 429, refused.text[:200]
    assert assert_error_envelope(refused)["code"] == "rate_limited"
    rows = svc.link_rows()
    assert len(rows) == 1, "the refused creation wrote a links row: " + repr(rows)
    assert svc.click_rows() == []
"}],"coverage_notes":"FILES AND CRITERIA
- tests/_pipeline_support.py: not a test file. Supplies a fresh SQLite DB per test (LINKS_DB_PATH under tmp_path), a freshly re-imported application per test (so the in-process rate-limiter dict and the parsed SHORTENER_API_KEYS snapshot start empty), a stubbed resolver (socket.getaddrinfo/gethostbyname), an error-envelope assertion, and a code-generator forcing fixture. No sleeps, no network, no shared state, no ordering dependence. It is deliberately NOT a conftest.py because tests/conftest.py already exists; fixtures are imported by name into each module.
- tests/test_pipeline_round_trip.py: round trip -> exact 307 plus Location equal to the stored URL byte for byte, Cache-Control no-store, short_url built from LINKS_BASE_URL with trailing slash stripped, row id never exposed.
- tests/test_pipeline_open_redirect.py: javascript:, JavaScript:, data: (two forms) and file: refused with 400 / error.code == unsupported_scheme AND links table verified empty afterwards (row absent, not just a 4xx); plus a guard that http/https are still accepted so the filter is not deny-all.
- tests/test_pipeline_private_targets.py: 169.254.169.254 (metadata), other link-local, loopback v4/v6/IPv4-mapped, 10/172.16/192.168 private ranges, CGNAT, 0.0.0.0, fd00::/fe80:: -> 400 blocked_destination with the links table verified empty; plus hostname-resolves-to-metadata, hostname-resolves-to-loopback, mixed public/private answer, decimal literal 2130706433 (mapped in the DNS stub to 127.0.0.1 so both literal-parsing and resolver-based implementations are held to the same bar), and a public-target-still-accepted guard.
- tests/test_pipeline_expiry.py: expiry is forced by writing expires_at in the past through the fixture (UPDATE on the row); never a sleep. Pins 410 + link_expired + no Location, no click row for the refused redirect, a future expiry still redirecting, a past expires_at refused at creation with no row, and stats still readable for an expired link.
- tests/test_pipeline_unknown_code.py: unknown code -> 404 not_found, no Location, links and clicks tables verified empty; malformed codes -> 404 rather than 500; stats 404; an existing link unaffected.
- tests/test_pipeline_click_analytics.py: exactly one click per successful redirect (asserted both in the clicks table and via total_clicks), three redirects -> three, a 404 redirect increments nothing, a 410 redirect increments nothing, per-link attribution, and no column in clicks capable of holding a visitor address.
- tests/test_pipeline_collision.py: the generator is forced to return an already-used code; the service must retry (generator consulted >= 2 times), still return 201 with a distinct unique code, keep both rows resolvable, and — when the generator always collides — give up with 503 code_generation_failed within a bounded number of attempts (<= 20, so a hang fails) while writing no extra row.
- tests/test_pipeline_rate_limit_keys.py: per-IP 11th creation -> 429 + Retry-After + no row; alpha:100 gets 100 x 201; the 101st -> 429 with {"error":{"code":"rate_limited"}} and exactly 100 rows and zero clicks; beta:20 stops at 21 (quotas are per key); an exhausted key does not block another key nor an unkeyed request from the same address; keyed successes do not consume the IP budget; unknown key gamma limited at the per-IP 10; blank/whitespace X-API-Key treated as absent; case-sensitivity (ALPHA falls back to the IP budget); every key-limited 429 carries Retry-After in [1,60] and Cache-Control: no-store; 50 redirects with an over-quota key all 307; the junk-entry string from the criteria boots and yields delta:7 while beta/gamma/broken degrade to the IP budget; " alpha : 100 " stripped; duplicate alpha last-wins; LINKS_RATE_LIMIT_ENABLED=false ignores quotas; LINKS_RATE_LIMIT_WINDOW_SECONDS=1 does not shrink the fixed 60s key window; stats and health unaffected while a key is over quota.
- tests/test_pipeline_key_hygiene.py: configured key names appear in no file under LINKS_DB_PATH's directory, in no captured log record, and in no response body or header; PRAGMA table_info(links)/(clicks) unchanged and no new table; a limiter-refused creation writes neither a links nor a clicks row.

DESIGN vs IMPLEMENTATION MISMATCHES (findings; tests follow the implementation as instructed)
1. Per-key rate limiting does not exist in the code shown. app/config.py never reads SHORTENER_API_KEYS and app/ratelimit.py has only "create"/"redirect" per-IP buckets keyed on the client address — no "key:" namespace, no ApiKeyQuotas mapping, no fixed 60s key window. Every test in tests/test_pipeline_rate_limit_keys.py that involves a recognised key therefore fails against the code as given; that is the feature under delivery.
2. Expired links: the design says GET /{code} must return 404 with code "not_found", byte-identical to a code that never existed (anti-enumeration oracle). The implementation returns 410 with code "link_expired", and the pre-existing tests/test_expiry.py pins that too. Per instruction I pinned the implementation (410 / link_expired). If the 404 decision is the real requirement, this suite and tests/test_expiry.py must both change — flagged as a genuine design/code conflict.
3. TTL configuration: design says LINKS_DEFAULT_TTL_SECONDS (default 0 = never expires) and a create field expires_in_seconds; the code uses LINKS_DEFAULT_TTL_DAYS (default 30) and expires_at. Tests use the implementation's names. The past-expiry creation test accepts 400 or 422 so it survives extra="forbid" if the field is renamed, and the core expiry test writes the row directly, so it is independent of the field name.
4. Defaults differ: design LINKS_RATE_LIMIT_MAX default 60, code default 10 (README documents 10). All limiter tests set the value explicitly, so the default is not relied on; the default itself is deliberately not asserted.
5. Data model: design says links.target_url and a clicks table with only id/link_id/clicked_at; the code has links.url and clicks.referrer/clicks.user_agent. The schema test asserts the implementation's columns (the criterion is "exactly the columns in app/db.py SCHEMA_STATEMENTS today"); DB reads elsewhere go through a tolerant url/target_url helper.
6. Stats response: the design's "expired" boolean does not exist in the implementation; not asserted anywhere.
7. Extra configuration in the code but absent from the design list: LINKS_TRUST_FORWARDED_FOR, LINKS_STATS_DEFAULT_LIMIT, LINKS_STATS_MAX_LIMIT, LINKS_DNS_RESOLUTION_ENABLED, LINKS_LOG_LEVEL. They are set to fixed values in BASE_ENV; no test asserts behaviour that depends on them except DNS resolution being enabled (needed for the hostname SSRF tests).

DELIBERATELY NOT COVERED
- Window expiry over real time (would require sleeping or clock injection the implementation does not expose), MAX_TRACKED_KEYS LRU eviction, concurrency/thread safety, X-Forwarded-For based per-IP separation (already covered by the repo's tests/test_rate_limit.py and it depends on LINKS_TRUST_FORWARDED_FOR, which the design does not list), pagination limits, and the health-degraded 503 path.
